CREATE TABLE public.developer_access_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text NOT NULL,
    phone text,
    company_name text NOT NULL,
    website text,
    project_name text,
    market text,
    note text,
    status text DEFAULT 'pending'::text NOT NULL,
    source text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    review_notes text,
    provisioned_user_id uuid,
    provisioned_account_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT developer_access_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'declined'::text])))
);


--

CREATE FUNCTION public.admin_decide_developer_access_request(_request_id uuid, _decision text, _notes text DEFAULT NULL::text) RETURNS public.developer_access_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_row public.developer_access_requests;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'admin role required';
  END IF;
  IF _decision NOT IN ('declined','pending') THEN
    RAISE EXCEPTION 'decision must be declined or pending (use admin_approve_developer_access_request to approve)';
  END IF;

  UPDATE public.developer_access_requests
     SET status = _decision,
         review_notes = COALESCE(_notes, review_notes),
         reviewed_by = auth.uid(),
         reviewed_at = now()
   WHERE id = _request_id
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'request not found';
  END IF;

  RETURN v_row;
END;
$$;


