CREATE FUNCTION public.admin_list_developer_access_requests(_status text DEFAULT 'all'::text) RETURNS TABLE(id uuid, first_name text, last_name text, email text, phone text, company_name text, website text, project_name text, market text, note text, status text, review_notes text, reviewed_at timestamp with time zone, created_at timestamp with time zone, provisioned_user_id uuid, provisioned_account_id uuid, activated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.id, r.first_name, r.last_name, r.email, r.phone, r.company_name,
         r.website, r.project_name, r.market, r.note, r.status, r.review_notes,
         r.reviewed_at, r.created_at, r.provisioned_user_id, r.provisioned_account_id,
         (
           select max(t.redeemed_at)
           from public.agent_activation_tokens t
           where t.user_id = r.provisioned_user_id
             and t.redeemed_at is not null
         ) as activated_at
  from public.developer_access_requests r
  where public.has_role(auth.uid(), 'admin'::app_role)
    and (_status = 'all' or r.status = _status)
  order by r.created_at desc
$$;


--

CREATE FUNCTION public.admin_provision_developer_access(_request_id uuid, _owner_user_id uuid, _account_name text DEFAULT NULL::text, _account_slug text DEFAULT NULL::text, _notes text DEFAULT NULL::text, _reviewer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_req public.developer_access_requests;
  v_account_id uuid;
  v_name text;
  v_slug text;
  v_base text;
  v_n int := 1;
  v_reviewer uuid;
  v_created boolean := false;
BEGIN
  IF NOT (public.jwt_role_text() = 'service_role' OR public.has_role(auth.uid(), 'admin')) THEN
    RAISE EXCEPTION 'admin role required' USING ERRCODE = '42501';
  END IF;

  IF _owner_user_id IS NULL THEN
    RAISE EXCEPTION 'owner user id is required' USING ERRCODE = '22023';
  END IF;

  v_reviewer := COALESCE(auth.uid(), _reviewer_id);

  SELECT * INTO v_req FROM public.developer_access_requests WHERE id = _request_id FOR UPDATE;
  IF v_req.id IS NULL THEN
    RAISE EXCEPTION 'request not found' USING ERRCODE = 'P0002';
  END IF;

  -- Idempotent replay: already provisioned.
  IF v_req.status = 'approved' AND v_req.provisioned_account_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'already_approved',
      'account_id', v_req.provisioned_account_id,
      'user_id', v_req.provisioned_user_id
    );
  END IF;

  -- Reuse an existing owner membership if this user already has one.
  SELECT m.account_id INTO v_account_id
  FROM public.development_account_members m
  JOIN public.development_accounts a ON a.id = m.account_id
  WHERE m.user_id = _owner_user_id AND m.role = 'owner'
  ORDER BY m.created_at
  LIMIT 1;

  IF v_account_id IS NULL THEN
    v_name := COALESCE(NULLIF(btrim(_account_name), ''), v_req.company_name);
    v_base := btrim(
      regexp_replace(lower(COALESCE(NULLIF(btrim(_account_slug), ''), v_name)), '[^a-z0-9]+', '-', 'g'),
      '-'
    );
    IF v_base = '' THEN
      v_base := 'developer';
    END IF;
    v_slug := v_base;
    WHILE EXISTS (SELECT 1 FROM public.development_accounts WHERE slug = v_slug) LOOP
      v_n := v_n + 1;
      v_slug := v_base || '-' || v_n::text;
    END LOOP;

    INSERT INTO public.development_accounts (name, slug, billing_email)
    VALUES (v_name, v_slug, v_req.email)
    RETURNING id INTO v_account_id;

    INSERT INTO public.development_account_members (account_id, user_id, role, invited_by, accepted_at)
    VALUES (v_account_id, _owner_user_id, 'owner', v_reviewer, now());

    v_created := true;
  END IF;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (_owner_user_id, 'developer'::public.app_role)
  ON CONFLICT (user_id, role) DO NOTHING;

  UPDATE public.developer_access_requests
     SET status = 'approved',
         reviewed_by = COALESCE(v_reviewer, reviewed_by),
         reviewed_at = now(),
         review_notes = COALESCE(_notes, review_notes),
         provisioned_user_id = _owner_user_id,
         provisioned_account_id = v_account_id
   WHERE id = _request_id;

  RETURN jsonb_build_object(
    'status', CASE WHEN v_created THEN 'approved' ELSE 'approved_existing_account' END,
    'account_id', v_account_id,
    'user_id', _owner_user_id
  );
END;
$$;


--

CREATE FUNCTION public.admin_replace_development_owner(_account_id uuid, _new_owner_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.has_role(auth.uid(), 'admin')
     and public.current_request_role() <> 'service_role' then
    raise exception 'admin role required';
  end if;

  perform 1 from public.development_accounts where id = _account_id for update;

  insert into public.development_account_members (account_id, user_id, role, invited_by, accepted_at)
  values (_account_id, _new_owner_user_id, 'owner', auth.uid(), now())
  on conflict (account_id, user_id) do update set role = 'owner';

  delete from public.development_account_members
  where account_id = _account_id and role = 'owner' and user_id <> _new_owner_user_id;
end $$;


--

CREATE FUNCTION public.admin_set_developer_role(_user_id uuid, _enabled boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'admin role required';
  END IF;
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'user_id is required';
  END IF;

  IF _enabled THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (_user_id, 'developer'::public.app_role)
    ON CONFLICT (user_id, role) DO NOTHING;
  ELSE
    DELETE FROM public.user_roles
    WHERE user_id = _user_id AND role = 'developer'::public.app_role;
  END IF;

  RETURN _enabled;
END;
$$;


