CREATE FUNCTION public.admin_set_development_account_active(_account_id uuid, _is_active boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.has_role(auth.uid(), 'admin')
     and public.current_request_role() <> 'service_role' then
    raise exception 'admin role required';
  end if;
  update public.development_accounts set is_active = _is_active where id = _account_id;
  if not found then raise exception 'Account not found'; end if;
  return _is_active;
end $$;


