CREATE FUNCTION public.agent_is_activation_eligible(_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.agent_is_activation_eligible(_user_id, false);
$$;


--

CREATE FUNCTION public.agent_is_activation_eligible(_user_id uuid, _allow_previously_deleted boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _email      text;
  _created_at timestamptz;
  _ok         boolean;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT lower(u.email), u.created_at
    INTO _email, _created_at
  FROM auth.users u
  WHERE u.id = _user_id
    AND u.deleted_at IS NULL
    AND (u.banned_until IS NULL OR u.banned_until <= now());

  IF _email IS NULL THEN
    RETURN false;
  END IF;

  IF NOT coalesce(_allow_previously_deleted, false) THEN
    IF EXISTS (
      SELECT 1
      FROM public.deleted_users d
      WHERE lower(d.email) = _email
        AND (
          d.original_user_id = _user_id
          OR d.deleted_at >= coalesce(_created_at, d.deleted_at)
        )
    ) THEN
      RETURN false;
    END IF;
  END IF;

  SELECT (pv.status IS DISTINCT FROM 'rejected' AND pv.rejected_at IS NULL)
    INTO _ok
    FROM public.pending_verifications pv
   WHERE pv.user_id = _user_id
   ORDER BY pv.created_at DESC
   LIMIT 1;

  IF _ok IS NOT NULL AND _ok IS NOT TRUE THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.agent_settings s
    JOIN public.user_roles r ON r.user_id = s.user_id AND r.role = 'agent'
    WHERE s.user_id = _user_id
      AND s.agent_status IN ('verified','invited')
      AND s.account_activated_at IS NULL
  );
END;
$$;


--

CREATE FUNCTION public.agent_is_login_eligible(_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _email text;
BEGIN
  IF _user_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT lower(u.email) INTO _email
  FROM auth.users u
  WHERE u.id = _user_id
    AND u.deleted_at IS NULL
    AND (u.banned_until IS NULL OR u.banned_until <= now());

  IF _email IS NULL THEN
    RETURN false;
  END IF;

  IF EXISTS (SELECT 1 FROM public.deleted_users d WHERE lower(d.email) = _email) THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$$;


