CREATE FUNCTION public.build_activation_email_payload(p_token_id uuid, p_to_email text, p_subject text, p_reply_to text, p_agent_name text, p_template text DEFAULT 'license-verified'::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  _subject text;
  _reply   text;
  _name    text;
  _template text;
BEGIN
  _template := lower(btrim(coalesce(p_template, 'license-verified')));
  IF _template NOT IN ('license-verified', 'agent-activation-reminder') THEN
    RAISE EXCEPTION 'unsupported activation email template' USING ERRCODE = '22023';
  END IF;

  _subject := left(btrim(coalesce(regexp_replace(p_subject, '[[:cntrl:]]', '', 'g'), '')), 200);
  IF _subject = '' THEN
    _subject := CASE _template
      WHEN 'agent-activation-reminder'
        THEN 'One last step — activate your All Agent Connect account'
      ELSE 'Your license has been verified — welcome to All Agent Connect'
    END;
  END IF;

  _reply := lower(btrim(coalesce(p_reply_to, '')));
  IF _reply !~ '^[a-z0-9._%+-]+@([a-z0-9-]+\.)*allagentconnect\.com$' THEN
    _reply := 'chris@allagentconnect.com';
  END IF;

  _name := left(btrim(coalesce(regexp_replace(p_agent_name, '[[:cntrl:]]', '', 'g'), '')), 80);

  RETURN jsonb_build_object(
    'provider', 'resend',
    'template', _template,
    'to', p_to_email,
    'subject', _subject,
    'reply_to', _reply,
    'agent_name', nullif(_name, ''),
    'activation_token_id', p_token_id::text,
    'idempotency_key', _template || '/' || p_token_id::text
  );
END;
$_$;


--

CREATE FUNCTION public.build_login_link_email_payload(p_token_id uuid, p_to_email text, p_subject text, p_reply_to text, p_agent_name text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
DECLARE
  _subject text;
  _reply   text;
  _name    text;
BEGIN
  _subject := left(btrim(coalesce(regexp_replace(p_subject, '[[:cntrl:]]', '', 'g'), '')), 200);
  IF _subject = '' THEN
    _subject := 'Your All Agent Connect sign-in link';
  END IF;

  _reply := lower(btrim(coalesce(p_reply_to, '')));
  IF _reply !~ '^[a-z0-9._%+-]+@([a-z0-9-]+\.)*allagentconnect\.com$' THEN
    _reply := 'chris@allagentconnect.com';
  END IF;

  _name := left(btrim(coalesce(regexp_replace(p_agent_name, '[[:cntrl:]]', '', 'g'), '')), 80);

  RETURN jsonb_build_object(
    'provider', 'resend',
    'template', 'agent-login-link',
    'to', p_to_email,
    'subject', _subject,
    'reply_to', _reply,
    'agent_name', nullif(_name, ''),
    'login_token_id', p_token_id::text,
    'idempotency_key', 'agent-login-link/' || p_token_id::text
  );
END;
$_$;


