CREATE TABLE public.hot_sheet_listing_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id uuid NOT NULL,
    trigger_op text NOT NULL,
    old_status text,
    new_status text NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone,
    claimed_at timestamp with time zone,
    claimed_by text,
    lease_expires_at timestamp with time zone,
    last_error text,
    dedupe_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT hot_sheet_listing_events_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'claimed'::text, 'processed'::text, 'paused_held'::text, 'skipped'::text, 'failed'::text])))
);


--

CREATE FUNCTION public.claim_hot_sheet_events(p_limit integer DEFAULT 10, p_worker_id text DEFAULT 'unknown'::text, p_lease_seconds integer DEFAULT 300) RETURNS SETOF public.hot_sheet_listing_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_service_role();

  RETURN QUERY
  UPDATE public.hot_sheet_listing_events e
     SET state = 'claimed',
         claimed_at = now(),
         claimed_by = p_worker_id,
         lease_expires_at = now() + make_interval(secs => GREATEST(p_lease_seconds, 30)),
         attempts = e.attempts + 1
   WHERE e.id IN (
     SELECT c.id
       FROM public.hot_sheet_listing_events c
      WHERE (c.state = 'pending' AND COALESCE(c.next_attempt_at, now()) <= now())
         OR (c.state = 'claimed' AND c.lease_expires_at IS NOT NULL AND c.lease_expires_at < now())
         OR (c.state = 'failed' AND c.next_attempt_at IS NOT NULL AND c.next_attempt_at <= now() AND c.attempts < 8)
      ORDER BY c.created_at
      LIMIT GREATEST(COALESCE(p_limit, 10), 1)
      FOR UPDATE SKIP LOCKED
   )
  RETURNING e.*;
END;
$$;


