CREATE FUNCTION public.cleanup_blocking_auth_identity(_email text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  repaired_count integer := 0;
BEGIN
  WITH repaired AS (
    UPDATE auth.identities i
    SET
      identity_data = jsonb_set(
        coalesce(i.identity_data, '{}'::jsonb),
        '{email}',
        to_jsonb(u.email),
        true
      ),
      updated_at = now()
    FROM auth.users u
    WHERE u.id = i.user_id
      AND lower(coalesce(i.identity_data->>'email', i.email)) = lower(trim(_email))
      AND lower(coalesce(u.email, '')) <> lower(trim(_email))
      AND u.email IS NOT NULL
    RETURNING 1
  )
  SELECT count(*) INTO repaired_count FROM repaired;

  RETURN repaired_count;
END;
$$;


--

CREATE FUNCTION public.cleanup_expired_share_tokens() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.share_tokens
  WHERE expires_at IS NOT NULL 
    AND expires_at < now();
END;
$$;


--

CREATE FUNCTION public.cleanup_orphan_auth_identity(_email text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
DECLARE
  deleted_count integer := 0;
BEGIN
  WITH del AS (
    DELETE FROM auth.identities i
    WHERE lower(i.identity_data->>'email') = lower(_email)
      AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = i.user_id)
    RETURNING 1
  )
  SELECT count(*) INTO deleted_count FROM del;
  RETURN deleted_count;
END;
$$;


