CREATE FUNCTION public.email_job_is_blocked(p_template text, p_idempotency_key text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(p_template, '') = 'agent-new-listing-alert'
      OR coalesce(p_idempotency_key, '') LIKE 'agent-new-listing:%';
$$;


--

CREATE TABLE public.email_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    run_after timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    last_error text,
    payload jsonb NOT NULL,
    idempotency_key text,
    provider_message_id text,
    delivery_status text,
    delivery_status_at timestamp with time zone,
    stream text,
    CONSTRAINT chk_email_job_status CHECK ((status = ANY (ARRAY['queued'::text, 'processing'::text, 'sent'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT email_jobs_stream_check CHECK (((stream IS NULL) OR (stream = ANY (ARRAY['hot_sheet'::text, 'communications'::text, 'transactional'::text, 'system'::text, 'development_notifications'::text]))))
);


--

CREATE FUNCTION public.email_jobs_claim(p_limit integer) RETURNS SETOF public.email_jobs
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN;
END;
$$;


--

CREATE FUNCTION public.email_jobs_claim(p_limit integer, p_streams text[]) RETURNS SETOF public.email_jobs
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_streams IS NULL OR array_length(p_streams, 1) IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH claimed AS (
    SELECT ej.id
    FROM public.email_jobs ej
    WHERE ej.status = 'queued'
      AND ej.run_after <= now()
      AND ej.stream IS NOT NULL
      AND ej.stream = ANY (p_streams)
      AND NOT public.email_job_is_blocked(ej.payload->>'template', ej.idempotency_key)
      AND ej.stream = public.email_stream_for_template(ej.payload->>'template')
    ORDER BY ej.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT p_limit
  )
  UPDATE public.email_jobs
  SET status = 'processing',
      attempts = attempts + 1
  FROM claimed
  WHERE email_jobs.id = claimed.id
  RETURNING email_jobs.*;
END;
$$;


--

CREATE FUNCTION public.email_jobs_enforce_stream() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_template text := NEW.payload->>'template';
  v_expected text := public.email_stream_for_template(NEW.payload->>'template');
BEGIN
  IF public.email_job_is_blocked(v_template, NEW.idempotency_key) THEN
    RAISE EXCEPTION 'email_jobs: template/idempotency_key is permanently retired (%).', coalesce(v_template, 'null');
  END IF;

  IF NEW.stream IS NULL THEN
    NEW.stream := v_expected;   -- NULL when unknown -> unclaimable, fail closed
  ELSIF v_expected IS NULL OR NEW.stream <> v_expected THEN
    NEW.stream := NULL;         -- mismatched -> unclaimable, fail closed
  END IF;

  RETURN NEW;
END;
$$;


--

CREATE FUNCTION public.email_jobs_stream_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.stream IS DISTINCT FROM OLD.stream THEN
    -- Allow a one-way backfill of a NULL stream to the canonical stream for
    -- the job's template (repair of rows inserted before the template was
    -- mapped). Any other change remains forbidden.
    IF OLD.stream IS NULL
       AND NEW.stream IS NOT NULL
       AND NEW.stream = public.email_stream_for_template(NEW.payload->>'template')
    THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'email_jobs.stream is immutable after insertion';
  END IF;
  RETURN NEW;
END;
$$;


--

CREATE FUNCTION public.email_stream_for_template(p_template text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE p_template
    WHEN 'new-match-notification' THEN 'hot_sheet'
    WHEN 'hot-sheet-status-change' THEN 'hot_sheet'
    WHEN 'hot-sheet-subscriber-status-change' THEN 'hot_sheet'
    WHEN 'hot-sheet-subscriber-update' THEN 'hot_sheet'
    WHEN 'hot-sheet-alert' THEN 'hot_sheet'
    WHEN 'hot-sheet-preview-blast' THEN 'hot_sheet'
    WHEN 'hot-sheet-preview-blast-test' THEN 'hot_sheet'
