CREATE FUNCTION public.enforce_development_slug_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.slug is distinct from old.slug and old.slug_locked_at is not null then
    raise exception 'The slug is locked once a development has been published';
  end if;
  return new;
end $$;


--

CREATE FUNCTION public.enforce_immutable_development_account() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.account_id is distinct from old.account_id then
    raise exception 'developments.account_id is immutable; a development cannot be re-parented';
  end if;
  return new;
end $$;


--

CREATE FUNCTION public.enforce_immutable_development_membership() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.account_id is distinct from old.account_id
     or new.user_id is distinct from old.user_id then
    raise exception 'development_account_members.account_id and user_id are immutable; delete and re-create the membership';
  end if;
  new.invited_by := old.invited_by;
  new.accepted_at := old.accepted_at;
  return new;
end $$;


--

CREATE FUNCTION public.enforce_last_development_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_account_id uuid := coalesce(old.account_id, new.account_id);
  remaining int;
begin
  if tg_op = 'UPDATE' and not (old.role = 'owner' and new.role <> 'owner') then
    return new;
  end if;
  if tg_op = 'DELETE' and old.role <> 'owner' then
    return old;
  end if;

  perform 1 from public.development_accounts where id = v_account_id for update;

  select count(*) into remaining
  from public.development_account_members m
  where m.account_id = v_account_id and m.role = 'owner' and m.id <> old.id;

  if remaining = 0 then
    raise exception 'A development account must retain at least one owner';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end $$;


