CREATE FUNCTION public.enqueue_hot_sheet_delivery(p_event_id uuid, p_listing_id uuid, p_status text, p_hot_sheet_id uuid, p_audience text, p_recipient_key text, p_payload jsonb, p_idempotency_key text, p_paused boolean DEFAULT true, p_pause_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_claim_id uuid;
  v_job_id uuid;
BEGIN
  PERFORM public.assert_service_role();

  IF p_event_id IS NULL THEN
    RAISE EXCEPTION 'event_id is required';
  END IF;
  IF p_recipient_key IS NULL OR btrim(p_recipient_key) = '' THEN
    RAISE EXCEPTION 'recipient_key is required';
  END IF;
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RAISE EXCEPTION 'idempotency_key is required';
  END IF;

  INSERT INTO public.hot_sheet_delivery_claims (
    listing_id, status_at_send, hot_sheet_id, audience, recipient_key, event_id, state, reason
  ) VALUES (
    p_listing_id, p_status, p_hot_sheet_id, p_audience, lower(btrim(p_recipient_key)),
    p_event_id, 'skipped', 'claiming'
  )
  ON CONFLICT (event_id, hot_sheet_id, audience, recipient_key) DO NOTHING
  RETURNING id INTO v_claim_id;

  IF v_claim_id IS NULL THEN
    RETURN jsonb_build_object('result', 'duplicate');
  END IF;

  IF COALESCE(p_paused, true) THEN
    UPDATE public.hot_sheet_delivery_claims
       SET state = 'paused_held',
           reason = COALESCE(p_pause_reason, 'hot_sheet_emails_paused')
     WHERE id = v_claim_id;
    RETURN jsonb_build_object('result', 'paused_held', 'claim_id', v_claim_id);
  END IF;

  INSERT INTO public.email_jobs (payload, stream, idempotency_key)
  VALUES (p_payload, 'hot_sheet', p_idempotency_key)
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING
  RETURNING id INTO v_job_id;

  IF v_job_id IS NULL THEN
    SELECT id INTO v_job_id
      FROM public.email_jobs
     WHERE idempotency_key = p_idempotency_key
     LIMIT 1;
  END IF;

  IF v_job_id IS NULL THEN
    RAISE EXCEPTION 'failed to resolve email job for idempotency_key %', p_idempotency_key;
  END IF;

  UPDATE public.hot_sheet_delivery_claims
     SET state = 'enqueued', email_job_id = v_job_id, reason = NULL
   WHERE id = v_claim_id;

  RETURN jsonb_build_object('result', 'enqueued', 'claim_id', v_claim_id, 'email_job_id', v_job_id);
END;
$$;


--

CREATE FUNCTION public.enqueue_message_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  recipient_email text;
  sender_name text;
  snippet text;
BEGIN
  -- Do not email self-sent
  IF NEW.recipient_agent_id IS NULL OR NEW.sender_agent_id = NEW.recipient_agent_id THEN
    RETURN NEW;
  END IF;

  -- Resolve recipient email: agent_profiles first, then profiles fallback
  SELECT ap.email INTO recipient_email
  FROM public.agent_profiles ap
  WHERE ap.id = NEW.recipient_agent_id;

  IF recipient_email IS NULL THEN
    SELECT p.email INTO recipient_email
    FROM public.profiles p
    WHERE p.id = NEW.recipient_agent_id;
  END IF;

  IF recipient_email IS NULL THEN
    RETURN NEW;
  END IF;

  -- Resolve sender display name (agent_profiles then profiles)
  SELECT CONCAT_WS(' ', ap.first_name, ap.last_name) INTO sender_name
  FROM public.agent_profiles ap
  WHERE ap.id = NEW.sender_agent_id;

  IF sender_name IS NULL OR sender_name = '' THEN
    SELECT CONCAT_WS(' ', p.first_name, p.last_name) INTO sender_name
    FROM public.profiles p
    WHERE p.id = NEW.sender_agent_id;
  END IF;

  IF sender_name IS NULL OR sender_name = '' THEN
    sender_name := 'Someone';
  END IF;

  snippet := left(coalesce(NEW.body, ''), 500);

  -- Enqueue with conversation_message:{id} idempotency to block duplicates
  INSERT INTO public.email_jobs (payload, idempotency_key)
  VALUES (
    jsonb_build_object(
      'provider', 'resend',
      'template', 'new-message-notification',
      'to', recipient_email,
      'subject', 'New message from ' || sender_name,
      'variables', jsonb_build_object(
        'sender_name', sender_name,
        'message_body', snippet,
        'conversation_id', NEW.conversation_id::text,
        'cta_url', '/messages/' || NEW.conversation_id::text
      )
    ),
    'conversation_message:' || NEW.id::text
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  RETURN NEW;
END;
$$;


--

CREATE FUNCTION public.enqueue_message_email_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payload jsonb;
BEGIN
  IF NEW.recipient_agent_id IS NULL OR NEW.recipient_agent_id = NEW.sender_agent_id THEN
    RETURN NEW;
  END IF;

  v_payload := public.build_message_email_payload(NEW.id);
  IF v_payload IS NULL THEN
    UPDATE public.conversation_messages SET email_enqueued_at = now() WHERE id = NEW.id;
    RETURN NEW;
  END IF;

  INSERT INTO public.email_jobs (payload, run_after)
  VALUES (v_payload, now() + interval '60 seconds');

  UPDATE public.conversation_messages SET email_enqueued_at = now() WHERE id = NEW.id;
  RETURN NEW;
END;
$$;


