CREATE FUNCTION public.fail_hot_sheet_event(p_event_id uuid, p_worker_id text, p_error text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  PERFORM public.assert_service_role();

  UPDATE public.hot_sheet_listing_events e
     SET state = 'failed',
         last_error = left(COALESCE(p_error, 'unknown error'), 2000),
         lease_expires_at = NULL,
         next_attempt_at = now() + LEAST(
           make_interval(secs => 60 * power(2, LEAST(e.attempts, 6))::int),
           interval '1 hour'
         )
   WHERE e.id = p_event_id
     AND e.claimed_by = p_worker_id
     AND e.lease_expires_at IS NOT NULL
     AND e.lease_expires_at > now();

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated > 0;
END;
$$;


