CREATE FUNCTION public.generate_listing_number() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  next_num INTEGER;
BEGIN
  next_num := nextval('listing_number_seq');
  RETURN 'L-' || next_num;
END;
$$;


