    CONSTRAINT chk_listing_status CHECK ((status = ANY (ARRAY['draft'::text, 'coming_soon'::text, 'active'::text, 'pending'::text, 'under_contract'::text, 'sold'::text, 'cancelled'::text, 'withdrawn'::text, 'temporarily_withdrawn'::text, 'off_market'::text, 'expired'::text, 'back_on_market'::text]))),
    CONSTRAINT chk_listings_draft_intended_status CHECK (((draft_intended_status IS NULL) OR (draft_intended_status = ANY (ARRAY['active'::text, 'coming_soon'::text, 'off_market'::text, 'back_on_market'::text, 'price_change'::text, 'extended'::text, 'reactivated'::text, 'under_agreement'::text, 'pending'::text, 'contingent'::text, 'sold'::text, 'rented'::text, 'temporarily_withdrawn'::text, 'cancelled'::text, 'expired'::text])))),
    CONSTRAINT dcmls_status_check CHECK ((dcmls_status = ANY (ARRAY['not_published'::text, 'published'::text, 'hidden'::text, 'error'::text]))),
    CONSTRAINT listings_commission_type_check CHECK ((commission_type = ANY (ARRAY['percentage'::text, 'flat_fee'::text]))),
    CONSTRAINT listings_listing_type_check CHECK ((listing_type = ANY (ARRAY['for_sale'::text, 'for_rent'::text, 'for_private_sale'::text])))
);


