    handicap_accessible,
    description,
    photos,
    floor_plans,
    virtual_tour_url,
    video_url,
    property_website_url,
    property_features,
    amenities,
    property_styles,
    construction_features,
    roof_materials,
    exterior_features_list,
    heating_types,
    cooling_types,
    green_features,
    foundation_types,
    basement_types,
    basement_features_list,
    basement_floor_types,
    parking_features_list,
    garage_features_list,
    garage_additional_features_list,
    outdoor_space,
    has_storage,
    storage_options,
    laundry_type,
    pet_options,
    pets_comment,
    area_amenities,
    condo_details,
    multi_family_details,
    commercial_details,
    open_houses,
    appointment_required,
    entry_only,
