CREATE FUNCTION public.get_hot_sheet_by_token(_token text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'id', hs.id,
    'user_id', hs.user_id,
    'client_id', hs.client_id,
    'name', hs.name,
    'criteria', hs.criteria,
    'is_active', hs.is_active,
    'notify_client_email', hs.notify_client_email,
    'notify_agent_email', hs.notify_agent_email,
    'notification_schedule', hs.notification_schedule,
    'last_sent_at', hs.last_sent_at,
    'created_at', hs.created_at,
    'updated_at', hs.updated_at
  )
  FROM public.share_tokens st
  JOIN public.hot_sheets hs
    ON hs.id = NULLIF(
         COALESCE(
           st.payload ->> 'hot_sheet_id',
           st.payload ->> 'hotSheetId',
           st.payload ->> 'hotsheetId'
         ),
         ''
       )::uuid
  WHERE st.token = _token
    AND st.revoked_at IS NULL
    AND (st.expires_at IS NULL OR st.expires_at > now())
  LIMIT 1;
$$;


--

CREATE FUNCTION public.get_hot_sheet_for_member(_hot_sheet_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _email text;
  _result jsonb;
BEGIN
  IF _uid IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT lower(email) INTO _email FROM public.profiles WHERE id = _uid;

  SELECT jsonb_build_object(
    'id', hs.id,
    'user_id', hs.user_id,
    'client_id', hs.client_id,
    'name', hs.name,
    'criteria', hs.criteria,
    'is_active', hs.is_active,
    'notify_client_email', hs.notify_client_email,
    'notify_agent_email', hs.notify_agent_email,
    'notification_schedule', hs.notification_schedule,
    'last_sent_at', hs.last_sent_at,
    'created_at', hs.created_at,
    'updated_at', hs.updated_at
  )
  INTO _result
  FROM public.hot_sheets hs
  WHERE hs.id = _hot_sheet_id
    AND (
      hs.user_id = _uid
      OR public.has_role(_uid, 'admin'::app_role)
      OR EXISTS (
        SELECT 1
        FROM public.hot_sheet_clients hsc
        JOIN public.clients c ON c.id = hsc.client_id
        WHERE hsc.hot_sheet_id = hs.id
          AND (c.agent_user_id = _uid OR (_email IS NOT NULL AND lower(c.email) = _email))
      )
      OR EXISTS (
        SELECT 1
        FROM public.clients c
        WHERE c.id = hs.client_id
          AND (c.agent_user_id = _uid OR (_email IS NOT NULL AND lower(c.email) = _email))
      )
      OR EXISTS (
        SELECT 1
        FROM public.share_tokens st
        WHERE NULLIF(
                COALESCE(
                  st.payload ->> 'hot_sheet_id',
                  st.payload ->> 'hotSheetId',
                  st.payload ->> 'hotsheetId'
                ),
                ''
              )::uuid = hs.id
          AND st.revoked_at IS NULL
          AND (
            st.accepted_by_user_id = _uid
            OR (_email IS NOT NULL AND lower(st.payload ->> 'client_email') = _email)
          )
      )
    );

  RETURN _result;
END;
$$;


--

CREATE FUNCTION public.get_listing_interest_signals(p_agent_id uuid, p_listing_ids uuid[]) RETURNS TABLE(listing_id uuid, saves_count bigint, comments_count bigint, hotsheet_match_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH agent_client_ids AS (
    -- CRM clients belonging to this agent
    SELECT c.id AS client_id
    FROM public.clients c
    WHERE c.agent_id = p_agent_id
  ),
  agent_client_user_ids AS (
    -- Auth user IDs of clients with active relationships to this agent
    SELECT car.client_id AS user_id
    FROM public.client_agent_relationships car
    WHERE car.agent_id = p_agent_id
      AND car.status = 'active'
  ),
  saves AS (
    SELECT f.listing_id, COUNT(*) AS cnt
    FROM public.favorites f
    WHERE f.listing_id = ANY(p_listing_ids)
      AND f.user_id IN (SELECT user_id FROM agent_client_user_ids)
    GROUP BY f.listing_id
  ),
  comments AS (
    SELECT hsc.listing_id, COUNT(DISTINCT hsc.sender_id) AS cnt
    FROM public.hot_sheet_comments hsc
    JOIN public.hot_sheets hs ON hs.id = hsc.hot_sheet_id
    WHERE hsc.listing_id = ANY(p_listing_ids)
      AND hs.user_id = p_agent_id
      AND hsc.sender_role = 'client'
    GROUP BY hsc.listing_id
  ),
  hs_matches AS (
    SELECT hsl.listing_id, COUNT(DISTINCT hsl.hot_sheet_id) AS cnt
    FROM public.hot_sheet_sent_listings hsl
    JOIN public.hot_sheets hs ON hs.id = hsl.hot_sheet_id
    WHERE hsl.listing_id = ANY(p_listing_ids)
      AND hs.user_id = p_agent_id
    GROUP BY hsl.listing_id
  ),
  all_listings AS (
    SELECT unnest(p_listing_ids) AS lid
  )
  SELECT
    al.lid AS listing_id,
    COALESCE(s.cnt, 0) AS saves_count,
    COALESCE(c.cnt, 0) AS comments_count,
    COALESCE(h.cnt, 0) AS hotsheet_match_count
  FROM all_listings al
  LEFT JOIN saves s ON s.listing_id = al.lid
  LEFT JOIN comments c ON c.listing_id = al.lid
  LEFT JOIN hs_matches h ON h.listing_id = al.lid
  WHERE COALESCE(s.cnt, 0) + COALESCE(c.cnt, 0) + COALESCE(h.cnt, 0) > 0;
$$;


--

CREATE FUNCTION public.get_newest_verified_agents(_limit integer DEFAULT 12) RETURNS TABLE(id uuid, first_name text, last_name text, company text, headshot_url text, office_city text, office_state text, verified_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT ap.id, ap.first_name, ap.last_name, ap.company, ap.headshot_url,
         ap.office_city, ap.office_state, s.verified_at
  FROM public.agent_settings s
  JOIN auth.users u
    ON u.id = s.user_id
  JOIN public.user_roles r
    ON r.user_id = s.user_id
   AND r.role = 'agent'::public.app_role
  JOIN public.agent_profiles ap
    ON ap.id = s.user_id
  WHERE s.agent_status = 'verified'::public.agent_status
    AND s.account_activated_at IS NOT NULL
    AND s.hide_from_directory = false
    AND btrim(coalesce(ap.first_name, '')) <> ''
    AND btrim(coalesce(ap.last_name, '')) <> ''
  ORDER BY GREATEST(
             COALESCE(s.account_activated_at, 'epoch'::timestamptz),
             COALESCE(s.verified_at,          'epoch'::timestamptz),
             COALESCE(ap.created_at,          'epoch'::timestamptz)
           ) DESC,
           s.verified_at DESC NULLS LAST,
           ap.created_at DESC
  LIMIT GREATEST(COALESCE(_limit, 12), 1);
$$;


