CREATE FUNCTION public.guard_development_account_system_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (new.is_active is distinct from old.is_active
      or new.stripe_customer_id is distinct from old.stripe_customer_id)
     and public.current_request_role() <> 'service_role'
     and not public.has_role(auth.uid(), 'admin') then
    raise exception 'is_active and stripe_customer_id are administered by AAC';
  end if;
  return new;
end $$;


--

CREATE FUNCTION public.guard_development_submission_triage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if public.current_request_role() = 'service_role' then
    new.updated_at := now();
    return new;
  end if;

  new.updated_at := now();

  if to_jsonb(new) - 'status' - 'assigned_contact_id' - 'updated_at'
     is distinct from to_jsonb(old) - 'status' - 'assigned_contact_id' - 'updated_at' then
    raise exception 'Only status and assigned_contact_id may be changed';
  end if;

  return new;
end $$;


--

CREATE FUNCTION public.guard_development_update_content() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.body_markdown ~* '<[a-z!/][^>]*>' then
    raise exception 'body_markdown must be Markdown; raw HTML is not allowed';
  end if;

  if tg_op = 'INSERT' then
    new.published_at := case when new.is_published then now() else null end;
  else
    if old.published_at is not null then
      new.published_at := old.published_at;          -- never rewritten
    elsif new.is_published and not old.is_published then
      new.published_at := now();                     -- first publish only
    else
      new.published_at := old.published_at;
    end if;
  end if;
  return new;
end $$;


