CREATE FUNCTION public.list_account_delegates_for_owner() RETURNS TABLE(member_id uuid, delegate_user_id uuid, invite_email text, display_name text, role_label text, status public.agent_delegate_status, invited_at timestamp with time zone, accepted_at timestamp with time zone, last_active_at timestamp with time zone, is_online boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    m.id,
    m.delegate_user_id,
    m.invite_email,
    m.display_name,
    m.role_label,
    m.status,
    m.invited_at,
    m.accepted_at,
    m.last_active_at,
    CASE
      WHEN m.delegate_user_id IS NULL THEN false
      ELSE EXISTS (
        SELECT 1
        FROM public.agent_settings s
        WHERE s.user_id = m.delegate_user_id
          AND s.last_seen_at > now() - interval '5 minutes'
      )
    END AS is_online
  FROM public.agent_account_members m
  WHERE m.owner_user_id = auth.uid()
    AND m.status IN ('invited', 'accepted')
  ORDER BY
    CASE m.status WHEN 'accepted' THEN 0 ELSE 1 END,
    m.display_name NULLS LAST,
    m.invite_email;
$$;


--

CREATE FUNCTION public.list_delegate_memberships() RETURNS TABLE(owner_user_id uuid, owner_first_name text, owner_last_name text, role_label text, display_name text, last_active_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    m.owner_user_id,
    ap.first_name,
    ap.last_name,
    m.role_label,
    m.display_name,
    m.last_active_at
  FROM public.agent_account_members m
  LEFT JOIN public.agent_profiles ap ON ap.id = m.owner_user_id
  WHERE m.delegate_user_id = auth.uid()
    AND m.status = 'accepted'
  ORDER BY ap.last_name NULLS LAST, ap.first_name NULLS LAST;
$$;


