CREATE FUNCTION public.mark_agent_activated(_user_id uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _now timestamptz := now();
  _existing timestamptz;
  _is_agent boolean;
  _caller uuid := auth.uid();
  _jwt_role text := public.jwt_role_text();
  _api boolean := public.is_api_request();
  _privileged boolean;
  _status text;
BEGIN
  IF _jwt_role = 'anon'
     OR (_caller IS NULL AND _jwt_role <> 'service_role' AND _api)
  THEN
    RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501';
  END IF;

  IF _user_id IS NULL THEN
    RETURN NULL;
  END IF;

  _privileged :=
    _jwt_role = 'service_role'
    OR (_caller IS NULL AND NOT _api)
    OR (_caller IS NOT NULL AND public.has_role(_caller, 'admin'));

  IF NOT _privileged AND _caller IS DISTINCT FROM _user_id THEN
    RETURN NULL;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = 'agent'
  ) INTO _is_agent;

  IF NOT _is_agent THEN
    RETURN NULL;
  END IF;

  SELECT agent_status INTO _status FROM public.agent_settings WHERE user_id = _user_id;

  IF NOT _privileged AND coalesce(_status, 'pending') NOT IN ('verified', 'invited') THEN
    RETURN NULL;
  END IF;

  PERFORM set_config('app.lifecycle_bypass', 'on', true);

  INSERT INTO public.agent_settings (user_id, account_activated_at, updated_at)
  VALUES (_user_id, _now, _now)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.agent_settings
     SET account_activated_at = _now, updated_at = _now
   WHERE user_id = _user_id AND account_activated_at IS NULL;

  UPDATE public.agent_settings
     SET agent_status = 'verified', verified_at = COALESCE(verified_at, _now), updated_at = _now
   WHERE user_id = _user_id AND agent_status = 'invited';

  PERFORM set_config('app.lifecycle_bypass', 'off', true);

  SELECT account_activated_at INTO _existing FROM public.agent_settings WHERE user_id = _user_id;
  RETURN _existing;
END;
$$;


