CREATE FUNCTION public.redeem_resend_handle_and_issue(p_handle_hash text, p_new_token_id uuid, p_new_token_hash text, p_expires_at timestamp with time zone, p_subject text DEFAULT NULL::text, p_reply_to text DEFAULT NULL::text, p_agent_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _handle public.agent_activation_resend_handles%ROWTYPE;
  _result jsonb;
BEGIN
  PERFORM public.assert_service_role();

  -- (1) Lock the handle. Not consumed yet.
  SELECT * INTO _handle
  FROM public.agent_activation_resend_handles
  WHERE handle_hash = lower(p_handle_hash)
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'invalid_handle');
  END IF;
  IF _handle.used_at IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'handle_used');
  END IF;
  IF _handle.expires_at <= now() THEN
    RETURN jsonb_build_object('status', 'handle_expired');
  END IF;

  -- (2)-(4) advisory lock + replacement token + queue job, atomically.
  _result := public.activation_issue_core(
    p_new_token_id,
    _handle.user_id,
    p_new_token_hash,
    p_expires_at,
    'resend:' || _handle.user_id::text || ':' || _handle.id::text,
    true,
    p_subject,
    p_reply_to,
    p_agent_name
  );

  IF _result->>'status' NOT IN ('created', 'deduped') THEN
    -- No token, no job, handle untouched.
    RETURN _result;
  END IF;

  -- (5) Only now is the single-use handle consumed.
  UPDATE public.agent_activation_resend_handles
     SET used_at = now()
   WHERE id = _handle.id AND used_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'resend handle consumed concurrently' USING ERRCODE = '40001';
  END IF;

  -- (6) Commit happens at statement end: token + job + handle together.
  RETURN _result;
END;
$$;


--

CREATE FUNCTION public.register_development_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.development_id_registry (id) values (new.id)
  ;   -- Review item 5: NO "on conflict do nothing". A previously registered id
      -- raises unique_violation and rolls back the development insert, so a
      -- purged development's UUID can never be reused.
  return new;
end $$;


--

CREATE FUNCTION public.reissue_agent_activation_token(p_id uuid, p_user_id uuid, p_token_hash text, p_expires_at timestamp with time zone, p_subject text DEFAULT NULL::text, p_reply_to text DEFAULT NULL::text, p_agent_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_service_role();

  RETURN public.activation_issue_core(
    p_id,
    p_user_id,
    p_token_hash,
    p_expires_at,
    'admin-resend:' || p_user_id::text || ':' || to_char(now() AT TIME ZONE 'utc', 'YYYYMMDDHH24MI'),
    true,
    p_subject,
    p_reply_to,
    p_agent_name
  );
END;
$$;


