CREATE FUNCTION public.reissue_agent_activation_token(p_id uuid, p_user_id uuid, p_token_hash text, p_expires_at timestamp with time zone, p_subject text DEFAULT NULL::text, p_reply_to text DEFAULT NULL::text, p_agent_name text DEFAULT NULL::text, p_allow_previously_deleted boolean DEFAULT false, p_template text DEFAULT 'license-verified'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM public.assert_service_role();

  RETURN public.activation_issue_core(
    p_id,
    p_user_id,
    p_token_hash,
    p_expires_at,
    'admin-resend:' || p_user_id::text || ':' || to_char(now() AT TIME ZONE 'utc', 'YYYYMMDDHH24MI'),
    true,
    p_subject,
    p_reply_to,
    p_agent_name,
    coalesce(p_allow_previously_deleted, false),
    p_template
  );
END;
$$;


