CREATE FUNCTION public.set_aac_id_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.aac_id IS NULL OR NEW.aac_id = '' THEN
    NEW.aac_id := public.generate_aac_id();
  END IF;
  RETURN NEW;
END;
$$;


