CREATE FUNCTION public.slugify_text(_txt text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT trim(both '-' FROM regexp_replace(lower(coalesce(_txt,'')), '[^a-z0-9]+', '-', 'g'));
$$;


