CREATE FUNCTION public.stamp_development_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
    new.created_by := auth.uid();
    new.updated_by := auth.uid();
    if public.current_request_role() <> 'service_role' then
      -- Review item 1 (defense in depth): a non-service caller can never create
      -- a development in any state other than draft, even if the column grant
      -- were widened by mistake. Publishing always goes through the matrix.
      if new.publish_status is distinct from 'draft' then
        raise exception 'New developments must be created as draft; publishing requires AAC review';
      end if;
      new.admin_notes := null;
      new.published_at := null;
      new.published_by := null;
      new.submitted_at := null;
      new.paused_at := null;
      new.archived_at := null;
      new.slug_locked_at := null;
    end if;
  else
    new.created_at := old.created_at;
    new.created_by := old.created_by;
    new.updated_at := now();
    new.updated_by := coalesce(auth.uid(), old.updated_by);
    if public.current_request_role() <> 'service_role'
       and not public.has_role(auth.uid(), 'admin')
       and new.admin_notes is distinct from old.admin_notes then
      raise exception 'admin_notes is administered by AAC';
    end if;
  end if;
  return new;
end $$;


--

CREATE FUNCTION public.stamp_development_child_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
    new.created_by := auth.uid();
    new.updated_by := auth.uid();
  else
    if new.development_id is distinct from old.development_id
       or new.account_id is distinct from old.account_id then
      raise exception 'development_id and account_id are immutable; a row cannot be moved between projects';
    end if;
    new.created_at := old.created_at;
    new.created_by := old.created_by;
    new.updated_at := now();
    new.updated_by := coalesce(auth.uid(), old.updated_by);
  end if;
  return new;
end $$;


