CREATE FUNCTION public.tg_teams_single_lead() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  n int;
BEGIN
  IF NEW.role = 'lead' AND NEW.status = 'accepted' THEN
    SELECT count(*) INTO n
    FROM public.team_members
    WHERE team_id = NEW.team_id
      AND role = 'lead'
      AND status = 'accepted'
      AND id <> NEW.id;
    IF n > 0 THEN
      RAISE EXCEPTION 'Team % already has an accepted lead', NEW.team_id
        USING ERRCODE = 'unique_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;


