    invite_expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval) NOT NULL,
    invited_by uuid NOT NULL,
    invited_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
