    CONSTRAINT agent_account_members_email_lower_chk CHECK ((invite_email = lower(TRIM(BOTH FROM invite_email)))),
    CONSTRAINT agent_account_members_no_self_delegate_chk CHECK (((delegate_user_id IS NULL) OR (delegate_user_id <> owner_user_id))),
    CONSTRAINT agent_account_members_revoked_chk CHECK ((((status = 'revoked'::public.agent_delegate_status) AND (revoked_at IS NOT NULL)) OR (status <> 'revoked'::public.agent_delegate_status)))
);


