    CONSTRAINT development_units_unit_features_check CHECK ((unit_features <@ ARRAY['balcony'::text, 'terrace'::text, 'private_roof_deck'::text, 'in_unit_laundry'::text, 'central_air'::text, 'fireplace'::text, 'walk_in_closet'::text, 'floor_to_ceiling_windows'::text, 'water_views'::text, 'city_views'::text, 'garage_parking'::text, 'ev_charging'::text, 'private_elevator'::text, 'smart_home'::text, 'storage'::text, 'other'::text])),
    CONSTRAINT development_units_unit_type_check CHECK (((unit_type IS NULL) OR (unit_type = ANY (ARRAY['studio'::text, 'flat'::text, 'duplex'::text, 'triplex'::text, 'loft'::text, 'penthouse'::text, 'townhome'::text, 'live_work'::text, 'commercial'::text]))))
);


