CREATE TABLE public.developments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    name text NOT NULL,
    slug text NOT NULL,
    slug_locked_at timestamp with time zone,
    logo_url text,
    stage text DEFAULT 'planning'::text NOT NULL,
    publish_status text DEFAULT 'draft'::text NOT NULL,
    published_at timestamp with time zone,
    published_by uuid,
    submitted_at timestamp with time zone,
    paused_at timestamp with time zone,
    archived_at timestamp with time zone,
    address text,
    city text,
    state text,
    postal_code text,
    latitude numeric(9,6),
    longitude numeric(9,6),
    neighborhood text,
    neighborhood_description text,
    developer_name text,
    architect_name text,
    interior_designer_name text,
    estimated_completion date,
    delivery_from date,
    delivery_to date,
    total_units integer,
    total_buildings integer,
    stories integer,
    year_built integer,
    construction_type text,
    building_details jsonb DEFAULT '{}'::jsonb NOT NULL,
    amenities jsonb DEFAULT '[]'::jsonb NOT NULL,
    parking_description text,
    parking_included boolean,
    pet_policy text,
    hoa_fees text,
    hoa_fee_min numeric(12,2),
    hoa_fee_max numeric(12,2),
    hoa_fee_includes text,
    deposit_structure text,
    incentives text,
    buyer_agent_compensation text,
    buyer_agent_compensation_notes text,
    description text,
    highlights jsonb DEFAULT '[]'::jsonb NOT NULL,
    tier text DEFAULT 'standard'::text NOT NULL,
    admin_notes text,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sales_status text DEFAULT 'not_yet_released'::text NOT NULL,
    expected_completion_year integer,
    expected_completion_quarter integer,
    expected_completion_month integer,
    actual_completion_date date,
    building_type text,
    building_amenities text[] DEFAULT '{}'::text[] NOT NULL,
    amenities_notes text,
    CONSTRAINT developments_actual_completion_requires_completed_check CHECK (((actual_completion_date IS NULL) OR (stage = 'completed'::text))),
    CONSTRAINT developments_building_amenities_check CHECK ((building_amenities <@ ARRAY['concierge_doorman'::text, 'elevator'::text, 'fitness_center'::text, 'pool'::text, 'roof_deck'::text, 'resident_lounge'::text, 'business_center'::text, 'package_room'::text, 'bike_storage'::text, 'garage_parking'::text, 'ev_charging'::text, 'storage'::text, 'pet_friendly'::text, 'dog_wash_pet_spa'::text, 'common_outdoor_space'::text, 'security'::text, 'other'::text])),
    CONSTRAINT developments_building_type_check CHECK (((building_type IS NULL) OR (building_type = ANY (ARRAY['high_rise'::text, 'mid_rise'::text, 'low_rise'::text, 'garden_style'::text, 'three_family'::text, 'two_family'::text, 'single_family'::text, 'townhomes'::text, 'condo_community'::text, 'loft_conversion'::text, 'brownstone'::text, 'mixed_use'::text, 'other'::text])))),
    CONSTRAINT developments_check CHECK (((delivery_from IS NULL) OR (delivery_to IS NULL) OR (delivery_from <= delivery_to))),
    CONSTRAINT developments_check1 CHECK (((hoa_fee_min IS NULL) OR (hoa_fee_max IS NULL) OR (hoa_fee_min <= hoa_fee_max))),
    CONSTRAINT developments_expected_completion_month_check CHECK (((expected_completion_month IS NULL) OR ((expected_completion_month >= 1) AND (expected_completion_month <= 12)))),
    CONSTRAINT developments_expected_completion_precision_check CHECK (((expected_completion_quarter IS NULL) OR (expected_completion_month IS NULL))),
    CONSTRAINT developments_expected_completion_quarter_check CHECK (((expected_completion_quarter IS NULL) OR ((expected_completion_quarter >= 1) AND (expected_completion_quarter <= 4)))),
    CONSTRAINT developments_expected_completion_requires_year_check CHECK (((expected_completion_year IS NOT NULL) OR ((expected_completion_quarter IS NULL) AND (expected_completion_month IS NULL)))),
    CONSTRAINT developments_expected_completion_year_check CHECK (((expected_completion_year IS NULL) OR ((expected_completion_year >= 2000) AND (expected_completion_year <= 2100)))),
    CONSTRAINT developments_publish_status_check CHECK ((publish_status = ANY (ARRAY['draft'::text, 'pending_review'::text, 'published'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT developments_sales_status_check CHECK ((sales_status = ANY (ARRAY['not_yet_released'::text, 'coming_soon'::text, 'now_selling'::text, 'final_units'::text, 'sold_out'::text]))),
    CONSTRAINT developments_stage_check CHECK ((stage = ANY (ARRAY['planning'::text, 'pre_construction'::text, 'under_construction'::text, 'completed'::text]))),
    CONSTRAINT developments_tier_check CHECK ((tier = ANY (ARRAY['standard'::text, 'featured'::text, 'premium'::text])))
);


