CREATE VIEW public.email_jobs_delivery_status WITH (security_invoker='true') AS
 SELECT id AS job_id,
    status AS queue_status,
    delivery_status,
    delivery_status_at,
    provider_message_id,
    (payload ->> 'template'::text) AS template,
    (payload ->> 'to'::text) AS recipient,
    (payload ->> 'subject'::text) AS subject,
    created_at,
    last_error,
    attempts,
    max_attempts
   FROM public.email_jobs j;


