CREATE VIEW public.listings_public WITH (security_invoker='false') AS
 SELECT id,
    agent_id,
    listing_number,
    status,
    listing_type,
    property_type,
    address,
    unit_number,
    building_name,
    city,
    town,
    state,
    zip_code,
    county,
    neighborhood,
    latitude,
    longitude,
    price,
    price_range_min,
    price_range_max,
    rental_fee,
    rental_fee_text,
    bedrooms,
    bathrooms,
    square_feet,
    lot_size,
    year_built,
    floors,
    garage_spaces,
    total_parking_spaces,
    parking_spaces,
    num_fireplaces,
    has_basement,
    waterfront,
    water_view,
    water_view_type,
    beach_nearby,
    handicap_access,
    handicap_accessible,
    description,
    photos,
    floor_plans,
    virtual_tour_url,
    video_url,
    property_website_url,
    property_features,
    amenities,
    property_styles,
    construction_features,
    roof_materials,
    exterior_features_list,
    heating_types,
    cooling_types,
    green_features,
    foundation_types,
    basement_types,
    basement_features_list,
    basement_floor_types,
    parking_features_list,
    garage_features_list,
    garage_additional_features_list,
    outdoor_space,
    has_storage,
    storage_options,
    laundry_type,
    pet_options,
    pets_comment,
    area_amenities,
    condo_details,
    multi_family_details,
    commercial_details,
    open_houses,
    appointment_required,
    entry_only,
    lender_owned,
    short_sale,
    annual_property_tax,
    tax_year,
    list_date,
    activation_date,
    active_date,
    go_live_date,
    created_at,
    updated_at,
    publish_to_dcmls,
    dcmls_status
   FROM public.listings l
  WHERE public.is_public_listing_status(status);


