CREATE TABLE public.notification_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    new_matches_enabled boolean DEFAULT true,
    price_changes_enabled boolean DEFAULT true,
    frequency text DEFAULT 'immediate'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    buyer_need boolean DEFAULT true NOT NULL,
    sales_intel boolean DEFAULT true NOT NULL,
    renter_need boolean DEFAULT true NOT NULL,
    general_discussion boolean DEFAULT true NOT NULL,
    min_price numeric,
    max_price numeric,
