CREATE VIEW public.v_email_job_engagement WITH (security_invoker='on') AS
 SELECT id AS job_id,
    created_at,
    (payload ->> 'template'::text) AS template,
    (payload ->> 'category'::text) AS category,
    delivery_status,
    ( SELECT count(*) AS count
           FROM public.email_job_opens o
          WHERE (o.job_id = j.id)) AS open_count,
    ( SELECT count(*) AS count
           FROM public.email_job_clicks c
          WHERE (c.job_id = j.id)) AS click_count,
    ( SELECT min(o.opened_at) AS min
           FROM public.email_job_opens o
          WHERE (o.job_id = j.id)) AS first_opened_at,
    ( SELECT min(c.clicked_at) AS min
           FROM public.email_job_clicks c
          WHERE (c.job_id = j.id)) AS first_clicked_at
   FROM public.email_jobs j;


--

CREATE VIEW public.v_email_unsubscribes_status WITH (security_invoker='on') AS
 SELECT email_lower AS email,
    array_agg(category ORDER BY category) AS categories,
    min(unsubscribed_at) AS first_unsubscribed_at,
    max(unsubscribed_at) AS last_unsubscribed_at
   FROM public.email_unsubscribes
  GROUP BY email_lower;


